// The generated module: the loaded graph as a typed constant (src/graph.generated.ts), so the site, the
// scheduler and the generators import the course's KC graph without reading YAML at run time. Pure.

import type { KcGraph } from './types.ts'

export const GENERATED_PATH = 'packages/kc/src/graph.generated.ts'

export function generateModule(graph: KcGraph): string {
  const body = JSON.stringify(graph, null, 2)
  return [
    '// GENERATED by `node scripts/verify-kc.mjs --write` from content/kc/graph.yaml. Do not edit: change the graph',
    '// and regenerate. GATE-kc fails while this file differs from what the graph generates.',
    '',
    "import type { KcGraph } from './types.ts'",
    '',
    `export const GRAPH: KcGraph = ${body}`,
    '',
  ].join('\n')
}
